<script setup lang="ts">
import { computed, ref } from 'vue'
import { api } from '../api/client'
import type { ProfileComposerPreflightResponse } from '../api/contracts'
import { useProfileDraft } from '../composables/useProfileDraft'
const { draft } = useProfileDraft()
const result = ref<ProfileComposerPreflightResponse | null>(null), error = ref(''), saving = ref(false), savedRef = ref('')
const highEffect = computed(() => draft.delivery === 'github_workflow')
async function preflight() { error.value = ''; try { result.value = await api.preflightProfileDraft(draft); if (!result.value.valid) error.value = '请先修复预检错误，再保存 Profile。'; return result.value.valid } catch (e) { error.value = e instanceof Error ? e.message : 'Profile 预检失败'; return false } }
async function save() { if (!(await preflight())) return; saving.value = true; error.value = ''; try { savedRef.value = (await api.saveProfileDraft(draft)).ref } catch (e) { error.value = e instanceof Error ? e.message : '保存 Profile 失败' } finally { saving.value = false } }
</script>
<template><section class="page profile-save"><div class="page-heading"><div><p class="eyebrow">PREFLIGHT → SAVE → REQUIREMENT INTAKE</p><h1>保存 Profile</h1><p>保存后该 Profile 会立即进入 Profile 库和新建需求页的下拉框。这里不做审批流程；执行时仍由需求页的“确认并执行”按钮触发。</p></div><RouterLink class="quiet-button" to="/profile-composer/form">返回编排</RouterLink></div><p v-if="error" class="data-warning">⚠ {{ error }}</p><section class="save-grid"><article class="workspace-panel"><h2>准备保存的组合</h2><dl><div><dt>组件链</dt><dd>{{ draft.source.name }} → {{ draft.compiler }} → {{ draft.maker }} → {{ draft.checkers.join(' + ') }} → {{ draft.delivery }}</dd></div><div><dt>权限</dt><dd>网络 {{ draft.policy.allow_network ? '允许' : '禁止' }} · 模型 {{ draft.policy.allow_model ? '允许' : '禁止' }} · Git {{ draft.policy.allow_git ? '允许' : '禁止' }} · 发布 {{ draft.policy.allow_publish ? '允许' : '禁止' }}</dd></div><div><dt>Source</dt><dd>{{ draft.source.config.backlog_path }} / {{ draft.source.config.state_path }}</dd></div></dl><p v-if="highEffect" class="data-warning">此 Profile 使用 GitHub Workflow。保存不会联网、生成或发布；只有后续新需求页中点击“确认并执行”才会触发真实链路。</p><button class="quiet-button" @click="preflight">重新预检</button><button class="primary-button" :disabled="saving" @click="save">{{ saving ? '正在保存…' : '保存到 Profile 库' }}</button></article><article class="workspace-panel"><h2>{{ result ? (result.valid ? '预检通过' : '预检未通过') : '尚未预检' }}</h2><p v-if="result?.valid" class="saved">✓ 规则校验通过，保存不会触发模型、网络、Git 或发布。</p><ul class="diagnostics"><li v-for="item in result?.diagnostics || []" :key="`${item.path}-${item.code}`" :class="item.severity"><code>{{ item.path }}</code> {{ item.message }}</li></ul><pre>{{ JSON.stringify(result?.normalized_profile || draft, null, 2) }}</pre></article></section><section v-if="savedRef" class="workspace-panel saved-panel"><h2>✓ {{ savedRef }} 已保存</h2><p>现在可以在“新建需求”选择它，执行：需求 → Plan Review → 保存需求 → 确认并执行。</p><RouterLink class="primary-button" to="/intake">去输入需求并执行</RouterLink><RouterLink class="quiet-button" to="/profiles">查看 Profile 库</RouterLink></section></section></template>
<style scoped>.save-grid{display:grid;grid-template-columns:.85fr 1.15fr;gap:13px}.profile-save h2{margin:0;font-size:15px}.profile-save dl{margin:16px 0}.profile-save dl div{padding:10px 0;border-top:1px solid var(--line-soft)}.profile-save dt{color:var(--soft);font-size:10px}.profile-save dd{margin:3px 0 0;overflow-wrap:anywhere;color:var(--muted);font-size:12px}.profile-save .quiet-button{margin:12px 8px 0 0}.diagnostics{padding-left:18px;font-size:11px}.diagnostics .error{color:var(--red)}.diagnostics .warning{color:var(--amber)}pre{max-height:350px;overflow:auto;margin:14px 0 0;padding:12px;border-radius:8px;background:var(--panel-2);font-size:10px}.saved-panel{margin-top:14px}.saved-panel p{color:var(--muted);font-size:12px}.saved-panel .quiet-button{margin-left:8px}@media(max-width:720px){.save-grid{grid-template-columns:1fr}.saved-panel .primary-button,.saved-panel .quiet-button{display:block;margin:10px 0 0}}</style>
